37	const char *helm_icon_text(helm_icon_t id)
38	{
39	    uint32_t cp;
40	
41	    if (id < 0 || id >= HELM_ICON_COUNT) {
42	        id = HELM_ICON_INFO;
43	    }
44	    cp = s_meta[id].cp;
45	    /* PUA 0xE000..0xF8FF 都是 3 字节 UTF-8 */
46	    s_utf8[0] = (char)(0xE0u | (cp >> 12));
47	    s_utf8[1] = (char)(0x80u | ((cp >> 6) & 0x3Fu));
48	    s_utf8[2] = (char)(0x80u | (cp & 0x3Fu));
49	    s_utf8[3] = '\0';
50	    return s_utf8;
51	}
