1952	/** 左簇墨迹布局：返回左簇最后一个墨迹 x1；pos[] 为各图标墨迹 x0（-1=隐藏）。 */
1953	static int left_cluster_layout(int x0, bool ble, bool hr, bool pwr, bool cad,
1954	                               int pos[5])
1955	{
1956	    const int w[5] = { 14, 12, 14, 14, 15 };
1957	    const bool on[5] = { true, ble, hr, pwr, cad };
1958	    int x = x0;
1959	    int end = x - 1;
1960	
1961	    for (int i = 0; i < 5; i++) {
1962	        if (!on[i]) {
1963	            pos[i] = -1;
1964	            continue;
1965	        }
1966	        pos[i] = x;
1967	        end = x + w[i] - 1;
1968	        x = end + 1 + INK_GAP_ICON;
1969	    }
1970	    return end;
1971	}
