2013	/** 建状态栏（环形页与骑行三页共用）。 */
2014	static void statusbar_build(void)
2015	{
2016	    char tbuf[16];
2017	    int time_end;
2018	    int pos[5];
2019	    bool show_ble = true;
2020	    bool cluster_off = !s_sens_on[0] && !s_sens_on[1] && !s_sens_on[2];
2021	    bool show_hr = !cluster_off;
2022	    bool show_pwr = !cluster_off;
2023	    bool show_cad = !cluster_off;
2024	    bool show_nav = s_nav_active;
2025	    bool show_rec = R.active && R.rec;
2026	    int left_end;
2027	    int right_left;
2028	    int x0;
2029	
2030	    memset(&SB, 0, sizeof(SB));
2031	    (void)B(s_scr, 0, 0, 240, 24, P_PAPER, LV_OPA_COVER, 0);
2032	    HAIR(s_scr, 0, 23, 240);
2033	
2034	    /* ① 时间：墨迹 x0=12（12px，贴左）。 */
2035	    snprintf(tbuf, sizeof(tbuf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
2036	    SB.time_l = LW(s_scr, tbuf, 12, P_INK, SB_TIME_X, 4,
2037	                   text_width(tbuf, 12) + 2, LV_TEXT_ALIGN_LEFT);
2038	    time_end = SB_TIME_X + text_width(tbuf, 12) - 1;
2039	
2040	    /* ② 左簇墨迹布局 + 碰撞保护（隐藏顺序 踏频→功率→NAV→BLE）。 */
2041	    x0 = time_end + 1 + INK_GAP_TIME;
2042	    for (int guard = 0; guard < 5; guard++) {
2043	        left_end = left_cluster_layout(x0, show_ble, show_hr, show_pwr,
2044	                                       show_cad, pos);
2045	        right_left = show_rec ? (show_nav ? SB_REC_NAV_X : SB_REC_X)
2046	                              : (show_nav ? 164 : SB_BAT_CX - 4);
2047	        if (right_left - left_end - 1 >= SB_MIN_BLANK) {
2048	            break;
2049	        }
2050	        if (show_cad) {
2051	            show_cad = false;
2052	            printf("helm: statusbar collision -> hide cadence\n");
2053	        } else if (show_pwr) {
2054	            show_pwr = false;
2055	            printf("helm: statusbar collision -> hide power\n");
2056	        } else if (show_nav) {
2057	            show_nav = false;
2058	            printf("helm: statusbar collision -> hide NAV\n");
2059	        } else if (show_ble) {
2060	            show_ble = false;
2061	            printf("helm: statusbar collision -> hide BLE\n");
2062	        } else {
2063	            break;
2064	        }
2065	    }
2066	    left_end = left_cluster_layout(x0, show_ble, show_hr, show_pwr, show_cad,
2067	                                   pos);
2068	
2069	    if (pos[0] >= 0) {
2070	        icon_at_ink(HELM_ICON_GPS, pos[0], 14, 6, 11, s_gps > 0);
2071	    }
2072	    if (pos[1] >= 0) {
2073	        icon_at_ink(HELM_ICON_BLE, pos[1], 12, 4, 9, s_ble_on);
2074	    }
2075	    if (pos[2] >= 0) {
2076	        icon_at_ink(HELM_ICON_HEART, pos[2], 14, 6, 11, s_sens_on[0]);
2077	    }
2078	    if (pos[3] >= 0) {
2079	        icon_at_ink(HELM_ICON_SPEED, pos[3], 14, 6, 11, s_sens_on[2]);
2080	    }
2081	    if (pos[4] >= 0) {
2082	        icon_at_ink(HELM_ICON_BIKE, pos[4], 15, 7, 12, s_sens_on[1]);
2083	    }
2084	
2085	    /* ③ 右簇：REC / NAV 以电量为锚点从右往左排。 */
2086	    {
2087	        int bat_x0 = SB_BAT_CX - 4;          /* 电池图标墨迹 182..189 */
2088	        int nav_x0 = 164;                    /* NAV 墨迹 164..173 */
2089	        int rec_x0 = show_nav ? SB_REC_NAV_X : SB_REC_X;
2090	
2091	        if (show_nav) {
2092	            SB.nav_i = scaled_icon(s_scr, HELM_ICON_NAV, SB_NAV_CX, 12, 14,
2093	                                   C_DEEP[M_NAV]);
2094	        }
2095	        if (show_rec) {
2096	            SB.rec_dot = B(s_scr, rec_x0, 9, 5, 5, P_RED, LV_OPA_COVER, 2);
2097	        }
2098	        SB.batt_i = scaled_icon(s_scr, HELM_ICON_BATTERY, SB_BAT_CX, 12, 10,
2099	                                s_batt < 20 ? P_RED : P_INK);
2100	        snprintf(tbuf, sizeof(tbuf), "%d%%", s_batt);
