2102	                       s_batt < 20 ? P_RED : P_INK, SB_BAT_TXT_X, 6,
2103	                       SB_BAT_TXT_W, LV_TEXT_ALIGN_RIGHT);
2104	        right_left = show_rec ? (show_nav ? SB_REC_NAV_X : SB_REC_X)
2105	                              : (show_nav ? nav_x0 : bat_x0);
2106	        (void)right_left;
